package com.notificationservice.presentation.controller;import com.notificationservice.application.port.in.ScheduleNotificationUseCase;import com.notificationservice.presentation.request.CreateScheduledNotificationRequest;import com.notificationservice.presentation.response.ApiResponse;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequestMapping("/api/v1/scheduled-notifications")@PreAuthorize("hasRole('SYSTEM_ADMIN')")public class ScheduledNotificationController{private final ScheduleNotificationUseCase useCase;public ScheduledNotificationController(ScheduleNotificationUseCase u){useCase=u;}@PostMapping public ApiResponse<UUID>create(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody CreateScheduledNotificationRequest r){var s=useCase.schedule(r.targetRole(),r.targetFaculty(),r.title(),r.content(),r.scheduledAt(),UUID.fromString(jwt.getSubject()));return ApiResponse.success(s.getId());}}
